# Atlas cache lab: 8x8 matrix multiply, i-j-k
# Generated by gen_bench.py (E8). Deterministic, no input; ends by running off the end.
# C = A x B, 8x8 words, row-major; inner loop walks a row of A and a column of B.
# 'addi x0, x0, 0' lines are padding: the nh-nf pipeline has no hazard unit, so every
# register write is followed by 2 nops and all five models compute the same addresses.
    lui x5, 0x10             # x5 = A = 0x10000
    addi x0, x0, 0
    addi x0, x0, 0
    addi x21, x5, 256        # x21 = B = 0x10100
    addi x0, x0, 0
    addi x0, x0, 0
    addi x22, x5, 512        # x22 = C = 0x10200
    addi x0, x0, 0
    addi x0, x0, 0
    addi x20, x0, 8          # x20 = N
    addi x0, x0, 0
    addi x0, x0, 0
    addi x23, x0, 64         # x23 = N*N
    addi x0, x0, 0
    addi x0, x0, 0
    addi x13, x0, 0          # init: A[k] = k+1, B[k] = 2k+1
    addi x0, x0, 0
    addi x0, x0, 0
init:
    slli x18, x13, 2
    addi x0, x0, 0
    addi x0, x0, 0
    add x19, x18, x5
    addi x0, x0, 0
    addi x0, x0, 0
    addi x24, x13, 1
    addi x0, x0, 0
    addi x0, x0, 0
    sw x24, 0(x19)
    add x19, x18, x21
    addi x0, x0, 0
    addi x0, x0, 0
    add x24, x24, x13
    addi x0, x0, 0
    addi x0, x0, 0
    sw x24, 0(x19)
    addi x13, x13, 1
    addi x0, x0, 0
    addi x0, x0, 0
    blt x13, x23, init
    addi x11, x0, 0          # i (outer)
    addi x0, x0, 0
    addi x0, x0, 0
L1:
    addi x12, x0, 0          # j (middle)
    addi x0, x0, 0
    addi x0, x0, 0
L2:
    addi x15, x0, 0          # sum = 0
    addi x0, x0, 0
    addi x0, x0, 0
    slli x16, x11, 5
    addi x0, x0, 0
    addi x0, x0, 0
    add x16, x16, x5         # x16 = &A[i][0]
    addi x0, x0, 0
    addi x0, x0, 0
    slli x17, x12, 2
    addi x0, x0, 0
    addi x0, x0, 0
    add x17, x17, x21        # x17 = &B[0][j]
    addi x0, x0, 0
    addi x0, x0, 0
    addi x13, x0, 0          # k
    addi x0, x0, 0
    addi x0, x0, 0
L3:
    lw x18, 0(x16)           # A[i][k]
    addi x0, x0, 0
    addi x0, x0, 0
    lw x19, 0(x17)           # B[k][j]
    addi x0, x0, 0
    addi x0, x0, 0
    mul x18, x18, x19
    addi x0, x0, 0
    addi x0, x0, 0
    add x15, x15, x18
    addi x0, x0, 0
    addi x0, x0, 0
    addi x16, x16, 4         # next column of A
    addi x0, x0, 0
    addi x0, x0, 0
    addi x17, x17, 32        # next row of B
    addi x0, x0, 0
    addi x0, x0, 0
    addi x13, x13, 1
    addi x0, x0, 0
    addi x0, x0, 0
    blt x13, x20, L3
    slli x18, x11, 5
    addi x0, x0, 0
    addi x0, x0, 0
    slli x19, x12, 2
    addi x0, x0, 0
    addi x0, x0, 0
    add x18, x18, x19
    addi x0, x0, 0
    addi x0, x0, 0
    add x18, x18, x22        # x18 = &C[i][j]
    addi x0, x0, 0
    addi x0, x0, 0
    sw x15, 0(x18)           # C[i][j] = sum
    add x8, x8, x15          # x8 = checksum
    addi x0, x0, 0
    addi x0, x0, 0
    addi x12, x12, 1
    addi x0, x0, 0
    addi x0, x0, 0
    blt x12, x20, L2
    addi x11, x11, 1
    addi x0, x0, 0
    addi x0, x0, 0
    blt x11, x20, L1
